<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$admin=require_admin($pdo);if(!admin_ops_ready($pdo)){http_response_code(503);exit('Admin V2.0 Operations requires migration 073.');}
$success='';$error='';$preview=null;$executed=null;$catalog=admin_ops_action_catalog();$accountPublic=trim((string)($_GET['account']??$_POST['account']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{
    $op=(string)($_POST['op']??'');
    if($op==='preview'){$preview=admin_ops_action_preview($pdo,$admin,(string)($_POST['action_type']??''),(string)($_POST['account']??''),(string)($_POST['reason']??''));$accountPublic=(string)($preview['preview']['account_public_id']??$accountPublic);$success='Governed action preview created. Review the exact action below before execution.';}
    elseif($op==='execute'){$executed=admin_ops_action_execute($pdo,$config,$admin,(string)($_POST['record_id']??''));$success='Governed action executed and recorded.';}
    else throw new RuntimeException('Unknown action-center operation.');
}catch(Throwable $e){$error=$e->getMessage();}}
$accounts=admin_ui_account_rows($pdo,[],300);$actions=admin_ops_recent_actions($pdo,150);$profile=admin_ops_operator_profile($pdo,$admin);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Action Center · Annotated Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?=admin_ui_sidebar('action_center')?>
<main class="panel adminActionCenterPage"><div class="pageTitle"><span class="eyebrow">ADMIN V2.0</span><h1>Governed action center</h1><p>Preview operational actions before execution. Every action requires an explicit reason, is tied to the acting administrator, and receives a durable correlation ID.</p></div>
<?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<section class="adminAccountSummaryGrid"><article class="card"><span class="meta">Operator role</span><strong><?=h((string)$profile['role_key'])?></strong></article><article class="card"><span class="meta">Execution model</span><strong>Preview → Execute</strong><small>No Agent execution authority</small></article><article class="card"><span class="meta">Governed actions</span><strong><?=h((string)count($catalog))?></strong></article></section>
<section class="adminAccountTwoCol"><article class="card"><span class="eyebrow">NEW ACTION</span><h2>Create preview</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="op" value="preview"><label>Account<select name="account" required><option value="">Select account</option><?php foreach($accounts as $a):?><option value="<?=h((string)$a['public_id'])?>" <?=$accountPublic===$a['public_id']?'selected':''?>><?=h((string)$a['name'])?> · <?=h((string)$a['package_name'])?></option><?php endforeach?></select></label><label>Action<select name="action_type" required><?php foreach($catalog as $key=>$meta):?><option value="<?=h($key)?>"><?=h((string)$meta['label'])?> · <?=h((string)$meta['risk'])?></option><?php endforeach?></select></label><label>Reason<textarea name="reason" rows="3" maxlength="500" required placeholder="Why is this action necessary?"></textarea></label><button>Preview governed action</button></form></article>
<article class="card"><span class="eyebrow">BOUNDARIES</span><h2>What V2.0 can execute</h2><?php foreach($catalog as $meta):?><div class="historyItem"><strong><?=h((string)$meta['label'])?></strong><div class="meta"><?=h(strtoupper((string)$meta['risk']))?> RISK</div><p><?=h((string)$meta['description'])?></p></div><?php endforeach?><p class="meta">Credits, refunds, lifecycle changes, membership changes, package changes and other higher-impact mutations remain in their existing explicit Admin surfaces. V2.0 records and unifies them but does not silently reroute them.</p></article></section>
<?php if($preview):$p=$preview['preview'];$rec=$preview['record'];?><section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">EXECUTION PREVIEW</span><h2><?=h((string)$p['label'])?></h2></div><span class="badge"><?=h(strtoupper((string)$p['risk_level']))?></span></div><div class="billingSubscriptionFacts"><div><span>Account</span><strong><?=h((string)$p['account_name'])?></strong></div><div><span>Package</span><strong><?=h((string)$p['package'])?></strong></div><div><span>Subscription</span><strong><?=h((string)$p['subscription_status'])?></strong></div><div><span>Correlation</span><strong><code><?=h(substr((string)$rec['correlation_id'],0,20))?>…</code></strong></div></div><p><?=h((string)$p['description'])?></p><?php if(!empty($p['warning'])):?><div class="error"><?=h((string)$p['warning'])?></div><?php endif?><?php if(array_key_exists('unreported_micros',$p)):?><p class="meta">Unreported AI overage: $<?=h(number_format(((int)$p['unreported_micros'])/1000000,6))?></p><?php endif?><?php if(array_key_exists('automatic_tax_enabled',$p)):?><p class="meta">Current automatic-tax policy: <?=!empty($p['automatic_tax_enabled'])?'enabled':'disabled'?></p><?php endif?><form method="post" class="inlineActions"><?=csrf_field()?><input type="hidden" name="op" value="execute"><input type="hidden" name="record_id" value="<?=h((string)$rec['public_id'])?>"><button>Execute reviewed action</button><a class="button secondary" href="/admin/action-center.php?account=<?=h(rawurlencode((string)$p['account_public_id']))?>">Cancel</a></form></section><?php endif?>
<section class="card"><div class="sectionHeadWeb"><div><span class="eyebrow">ACTION LEDGER</span><h2>Recent governed Admin actions</h2></div></div><div class="tableWrap"><table><thead><tr><th>Time</th><th>Action</th><th>Account</th><th>Actor</th><th>Risk</th><th>Status</th><th>Reason</th><th>Correlation</th></tr></thead><tbody><?php foreach($actions as $a):?><tr><td><?=h((string)$a['created_at'])?></td><td><?=h(ucwords(str_replace('_',' ',(string)$a['action_type'])))?></td><td><?php if($a['account_public_id']):?><a href="/admin/account.php?id=<?=h(rawurlencode((string)$a['account_public_id']))?>"><?=h((string)$a['account_name'])?></a><?php else:?>—<?php endif?></td><td><?=h((string)$a['actor_username'])?></td><td><?=h((string)$a['risk_level'])?></td><td><?=h((string)$a['status'])?></td><td><?=h((string)$a['reason'])?></td><td><code><?=h(substr((string)$a['correlation_id'],0,16))?>…</code></td></tr><?php endforeach?><?php if(!$actions):?><tr><td colspan="8" class="empty">No V2.0 governed actions yet.</td></tr><?php endif?></tbody></table></div></section>
</main></body></html>
